/* Disabled until a real analytics adapter and the site's consent state exist.
 * It does not create page views, store IDs, or send private state. */
(()=>{'use strict';const events=new Set(['calculator_completed','checklist_export','compatibility_check_completed','diagnostic_result_generated','upgrade_result_generated','upgrade_export','guided_plan_updated','build_revision_saved','build_shared','comparison_completed','comparison_shared','retailer_outbound','guide_builder_open']),keys=new Set(['page_type','category','region','action','merchant']),recent=new Map();window.PCP_EVENTS={track(name,params={}){const adapter=window.PCP_ANALYTICS;if(!adapter?.enabled||adapter.consentGranted!==true||typeof adapter.send!=='function'||!events.has(name))return false;const safe={};for(const [k,v]of Object.entries(params))if(keys.has(k)&&typeof v==='string'&&/^[a-zA-Z0-9 _-]{1,40}$/.test(v))safe[k]=v;const id=name+JSON.stringify(safe),now=Date.now();if(now-(recent.get(id)||0)<750)return false;recent.set(id,now);try{adapter.send(name,safe);return true}catch{return false}}};})();
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{if(document.body.dataset.page!=='builder'||!document.referrer)return;try{const previous=new URL(document.referrer);if(previous.origin===location.origin&&(/^\/blog\//.test(previous.pathname)||previous.pathname==='/build-school/'))window.PCP_EVENTS.track('guide_builder_open',{page_type:'builder',action:'destination_loaded'})}catch{}},{once:true});
